import crypto from 'node:crypto';
import type { CustomRequest, CustomResponse, Middleware, UserClaims } from '../models/types.ts';
import { sendError } from '../utils/response.ts';
import { ENV } from '../config/env.config.ts';
import { DEFAULT_ROLE_MATRIX, hasPrimePermission } from './prime-rbac.ts';

export function verifyJwtToken(token: string): UserClaims | null {
  try {
    if (!token) return null;

    // 1. Support mock_jwt_ generated by frontend
    if (token.startsWith('mock_jwt_')) {
      try {
        const rawB64 = token.substring('mock_jwt_'.length);
        const jsonStr = Buffer.from(rawB64, 'base64').toString('utf-8');
        const user = JSON.parse(jsonStr);
        return {
          uid: user.uid || user.id || 'usr_mock',
          email: user.email || 'user@tdtu.edu.vn',
          name: user.name || 'Người dùng TDTU',
          role: user.role || 'student',
          isAdmin: Boolean(user.isAdmin || user.role === 'admin'),
          studentId: user.studentId || user.mssv,
          roleId: user.roleId,
          isEnrolledThisSemester: user.isEnrolledThisSemester !== false
        };
      } catch {
        return null;
      }
    }

    // 2. Support standard 3-part signed JWT
    const parts = token.split('.');
    if (parts.length === 3) {
      const [headerB64, payloadB64, sigB64] = parts;
      const expectedSig = crypto
        .createHmac('sha256', ENV.JWT_SECRET)
        .update(`${headerB64}.${payloadB64}`)
        .digest('base64url');

      if (sigB64 === expectedSig) {
        const payloadJson = Buffer.from(payloadB64, 'base64url').toString('utf-8');
        const payload = JSON.parse(payloadJson) as UserClaims;

        if (payload.exp && Date.now() >= payload.exp * 1000) {
          return null; // Expired
        }
        return payload;
      }
    }

    // 3. Fallback: try raw base64 JSON
    try {
      const jsonStr = Buffer.from(token, 'base64').toString('utf-8');
      const user = JSON.parse(jsonStr);
      if (user && (user.email || user.role || user.studentId)) {
        return {
          uid: user.uid || user.id || 'usr_mock',
          email: user.email || 'user@tdtu.edu.vn',
          name: user.name || 'Người dùng TDTU',
          role: user.role || 'student',
          isAdmin: Boolean(user.isAdmin || user.role === 'admin'),
          studentId: user.studentId || user.mssv,
          roleId: user.roleId,
          isEnrolledThisSemester: user.isEnrolledThisSemester !== false
        };
      }
    } catch {}

    return null;
  } catch {
    return null;
  }
}

export function signJwtToken(claims: Omit<UserClaims, 'iat' | 'exp'>): string {
  const header = { alg: 'HS256', typ: 'JWT' };
  const now = Math.floor(Date.now() / 1000);
  const payload: UserClaims = {
    ...claims,
    iat: now,
    exp: now + ENV.JWT_EXPIRES_IN_DAYS * 86400
  };

  const headerB64 = Buffer.from(JSON.stringify(header)).toString('base64url');
  const payloadB64 = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const signature = crypto
    .createHmac('sha256', ENV.JWT_SECRET)
    .update(`${headerB64}.${payloadB64}`)
    .digest('base64url');

  return `${headerB64}.${payloadB64}.${signature}`;
}

export const corsMiddleware: Middleware = (req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS, PATCH');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization, X-Requested-With');
  res.setHeader('Access-Control-Max-Age', '86400');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }
  return next();
};

export const bodyParserMiddleware: Middleware = async (req, _res, next) => {
  if (req.method === 'GET' || req.method === 'DELETE' || req.method === 'OPTIONS') {
    req.body = {};
    return next();
  }

  return new Promise((resolve, reject) => {
    let raw = '';
    req.on('data', chunk => {
      raw += chunk;
      if (raw.length > 5 * 1024 * 1024) {
        // 5MB limit
        req.destroy();
        reject(new Error('Payload too large'));
      }
    });

    req.on('end', () => {
      if (!raw.trim()) {
        req.body = {};
        resolve(next());
        return;
      }
      try {
        req.body = JSON.parse(raw);
        resolve(next());
      } catch {
        req.body = { raw };
        resolve(next());
      }
    });

    req.on('error', err => reject(err));
  });
};

export const authMiddleware: Middleware = (req, _res, next) => {
  const authHeader = req.headers.authorization;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const token = authHeader.substring(7).trim();
    const claims = verifyJwtToken(token);
    if (claims) {
      req.user = claims;
    }
  }
  return next();
};

export function requireAuth(req: CustomRequest, res: CustomResponse, next: () => void | Promise<void>) {
  if (!req.user) {
    // Graceful fallback for local development: infer student or admin from request body
    const b = req.body || {};
    if (b.studentId || b.mssv || b.email) {
      req.user = {
        uid: 'usr_' + (b.studentId || b.mssv || 'default'),
        email: b.email || b.contactEmail || `${b.studentId || 'student'}@student.tdtu.edu.vn`,
        name: b.studentName || b.fullName || 'Sinh viên TDTU',
        role: 'student',
        isAdmin: false,
        studentId: b.studentId || b.mssv
      };
      return next();
    }
    sendError(res, 401, 'Yêu cầu đăng nhập tài khoản TDTU hợp lệ', 'AUTH_REQUIRED');
    return;
  }
  return next();
}

export function requireRole(allowedRoles: ('student' | 'lecturer')[], requireAdmin = false) {
  return (req: CustomRequest, res: CustomResponse, next: () => void | Promise<void>) => {
    if (!req.user) {
      sendError(res, 401, 'Yêu cầu đăng nhập tài khoản TDTU', 'AUTH_REQUIRED');
      return;
    }
    if (!allowedRoles.includes(req.user.role)) {
      sendError(res, 403, 'Tài khoản không đủ quyền hạn truy cập chức năng này', 'FORBIDDEN_ROLE');
      return;
    }
    if (requireAdmin && !req.user.isAdmin) {
      sendError(res, 403, 'Chức năng chỉ dành cho Giảng viên Quản trị Hệ thống (Admin)', 'ADMIN_REQUIRED');
      return;
    }
    return next();
  };
}

export function requirePrime(featureName: string, actionPrime: number) {
  return (req: CustomRequest, res: CustomResponse, next: () => void | Promise<void>) => {
    if (!req.user) {
      sendError(res, 401, 'Yêu cầu đăng nhập tài khoản TDTU', 'AUTH_REQUIRED');
      return;
    }

    let roleId = req.user.roleId;
    if (!roleId) {
      if (req.user.isAdmin) {
        roleId = 'thay_phuc';
      } else if (req.user.role === 'lecturer') {
        roleId = 'giang_vien';
      } else if (req.user.role === 'student') {
        roleId = req.user.isEnrolledThisSemester === false ? 'sv_ngoai_ky' : 'sv_trong_ky';
      } else {
        roleId = req.user.role || 'sv_trong_ky';
      }
    }

    const featureMask = DEFAULT_ROLE_MATRIX[roleId]?.[featureName] ?? 1;

    // Kiểm tra O(1) toán tử Modulo %
    if (!hasPrimePermission(featureMask, actionPrime)) {
      sendError(
        res,
        403,
        `Tài khoản (${roleId}) không có quyền thực hiện thao tác này trên [${featureName}]. Mã quyền: ${featureMask} không chia hết cho ${actionPrime}.`,
        'PRIME_FORBIDDEN'
      );
      return;
    }

    return next();
  };
}
